const fs = require('fs').promises;

async function main() {
    const apiKey = process.env.CROSSMINT_API_KEY;
    if (!apiKey) {
        console.error("CROSSMINT_API_KEY environment variable is missing.");
        process.exit(1);
    }

    let recipients = [];
    try {
        const data = await fs.readFile('/home/user/recipients.json', 'utf8');
        recipients = JSON.parse(data);
    } catch (err) {
        console.error("Failed to read recipients.json:", err.message);
        process.exit(1);
    }

    const summary = {
        total: recipients.length,
        results: []
    };

    for (const email of recipients) {
        const recipientStr = `email:${email}:polygon-amoy`;
        const body = {
            recipient: recipientStr,
            metadata: {
                name: "Welcome NFT",
                description: "Airdrop token",
                image: "https://example.com/welcome.png"
            }
        };

        try {
            const response = await fetch('https://staging.crossmint.com/api/2022-06-09/collections/default/nfts', {
                method: 'POST',
                headers: {
                    'x-api-key': apiKey,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(body)
            });

            // Attempt to parse response as JSON, fallback to text
            let responseData;
            const textResponse = await response.text();
            try {
                responseData = JSON.parse(textResponse);
            } catch (e) {
                responseData = textResponse;
            }

            if (response.status === 200 || response.status === 202) {
                summary.results.push({
                    email,
                    status: 'sent',
                    response: responseData
                });
            } else {
                summary.results.push({
                    email,
                    status: 'error',
                    response: responseData
                });
            }
        } catch (error) {
            summary.results.push({
                email,
                status: 'error',
                response: error.message
            });
        }
    }

    try {
        await fs.writeFile('/home/user/airdrop_summary.json', JSON.stringify(summary, null, 2), 'utf8');
        console.log("Airdrop summary written to /home/user/airdrop_summary.json");
    } catch (err) {
        console.error("Failed to write airdrop_summary.json:", err.message);
    }
}

